package com.gymmind.membership.application; import com.gymmind.membership.domain.model.*; import java.time.Instant; public record MemberMembershipView(Long id,Long tenantId,Long memberId,Long packageId,Integer remainingCount,Instant startsAt,Instant expiresAt,MemberMembershipStatus status){static MemberMembershipView from(MemberMembership m){return new MemberMembershipView(m.getId(),m.getTenantId(),m.getMemberId(),m.getPackageId(),m.getRemainingCount(),m.getStartsAt(),m.getExpiresAt(),m.getStatus());}}
